def append(path, row, guard):
    txt = io.open(path, encoding='utf-8').read()
    assert guard not in txt, 'guard tripped for %s (already present)' % path
    if not txt.endswith(u'\n'):
        txt += u'\n'
    io.open(path, 'w', encoding='utf-8', newline='\n').write(txt + row)
    print('appended:', path)

